{"query": "import re

# Extract the first numerical value from each entry
def extract_first_number(text):
    if pd.isna(text) or text == '':
        return 0

    # Find all numbers in the text
    numbers = re.findall(r'\d+', str(text))

    if numbers:
        return int(numbers[0])
    else:
        # Handle special cases like ">20" and "<250"
        if '>' in str(text):
            # For ">20", use the number after >
            match = re.search(r'>\s*(\d+)', str(text))
            if match:
                return int(match.group(1))
        elif '<' in str(text):
            # For "<250", use the number after <
            match = re.search(r'<\s*(\d+)', str(text))
            if match:
                return int(match.group(1))
        return 0

# Apply the function to create a new column with numerical values
df['InService_numeric'] = df['InService_clean2'].apply(extract_first_number)

print("InService values after cleaning:")
for i, row in df.iterrows():
    print(f"Row {i}: '{row['InService']}' -> '{row['InService_clean2']}' -> {row['InService_numeric']}")"}

